def pat(a): return re.compile('[  ]'.join(re.escape(x) for x in a.split(' ')))
for fn in sys.argv[1:]:
    s = io.open(fn, encoding='utf-8-sig').read(); miss = []
    for a, b in R:
        s, k = pat(a).subn(lambda m: b, s)
        if k == 0: miss.append(a[:50])
    io.open(fn, 'w', encoding='utf-8-sig').write(s)
    print(fn, 'не найдено:', len(miss)); [print('   ', m) for m in miss]
